deps = {"system.img": ["framework.jar", "libvhal.so"], "framework.jar": ["libcarutil.so"],
        "libvhal.so": ["libcarutil.so"], "libcarutil.so": []}
def order(deps):
    seen, done, out = set(), set(), []
    def visit(n, path):
        if n in done: return
        if n in seen: raise SystemExit("cycle: " + " -> ".join(path + [n]))
        seen.add(n)
        for d in deps[n]: visit(d, path + [n])
        done.add(n); out.append(n)
    for n in deps: visit(n, [])
    return out
print(order(deps))
deps["libcarutil.so"] = ["libvhal.so"]
order(deps)

# ['libcarutil.so', 'framework.jar', 'libvhal.so', 'system.img']
# cycle: system.img -> framework.jar -> libcarutil.so -> libvhal.so -> libcarutil.so
